const todayStr = new Date().toLocaleDateString('fr-FR', {
  timeZone: 'Europe/Paris',
  day: '2-digit',
  month: '2-digit',
  year: 'numeric'
});

return items.filter(item => {
  const date = (item.json['Date'] || '').trim();
  const statut = (item.json['Statut'] || '').trim();
  return date === todayStr && statut === 'À publier';
});

const sheetData = $('Filtrer articles du jour').item.json;
const content = $input.item.json.content[0].text || '';

if (!content) throw new Error('Contenu Claude vide');

const titre = sheetData['Titre'] || '';
const categorie = sheetData['Catégorie'] || '';
const imageUrl = sheetData['Image URL'] || '';
const date = sheetData['Date'] || '';
const rowNumber = sheetData['row_number'] || '';

const parts = date.split('/');
const isoDate = parts.length === 3 ? `${parts[2]}-${parts[1]}-${parts[0]}` : date;

const slug = titre
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/['']/g, '')
  .replace(/[^a-z0-9\s-]/g, '')
  .trim()
  .replace(/\s+/g, '-')
  .replace(/-+/g, '-');

const cleanContent = content
  .replace(/^#{1,6}\s.+$/gm, '')
  .replace(/\*\*([^*]+)\*\*/g, '$1')
  .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
  .replace(/\n+/g, ' ')
  .trim();
const description = (cleanContent.length > 157
  ? cleanContent.substring(0, 157) + '...'
  : cleanContent
).replace(/"/g, "'");

const titreEscaped = titre.replace(/"/g, "'");
const mdx = `---\ntitle: "${titreEscaped}"\ndescription: "${description}"\npubDate: ${isoDate}\nimage: "${imageUrl}"\nimageAlt: "${titreEscaped}"\ncategory: "${categorie}"\n---\n\n${content}`;

const mdxBase64 = Buffer.from(mdx, 'utf-8').toString('base64');

return [{ json: { slug, mdxBase64, titre, date, isoDate, rowNumber, categorie, imageUrl } }];
